// ============================================
// Filter state <-> URL
// A filtered archive should be a link you can send someone, and it should
// survive the round trip out to a case study and back. "ALL" and an empty
// query are the defaults, so they stay out of the URL entirely.
// ============================================
const FILTER_IDS = FILTER_CATEGORIES.map((c) => c.id);

const readFilterUrl = (search) => {
  const params = new URLSearchParams(search);
  const raw = (params.get("filter") || "").toUpperCase();
  return {
    category: FILTER_IDS.includes(raw) ? raw : "ALL",
    query: params.get("q") || "",
  };
};

const buildFilterUrl = (category, query) => {
  const params = new URLSearchParams();
  if (category && category !== "ALL") params.set("filter", category.toLowerCase());
  if (query.trim()) params.set("q", query.trim());
  const qs = params.toString();
  return qs ? `?${qs}` : "";
};

// Extract the most relevant year from a timeline string ("June 2024 - Present", "2025")
const extractYear = (timeline) => {
  if (!timeline) return null;
  if (/present/i.test(timeline)) {
    const matches = timeline.match(/(20\d{2})/g);
    if (matches && matches.length) return matches[matches.length - 1];
    return "Present";
  }
  const matches = timeline.match(/(20\d{2})/g);
  if (!matches) return null;
  return matches[matches.length - 1];
};

// Build a haystack string for searching/filtering a single project
const buildHaystack = (project) => {
  const techNames = (project.languages || [])
    .map((l) => (l.name || "").toLowerCase())
    .join(" ");
  return `${(project.name || "").toLowerCase()} ${(
    project.description || ""
  ).toLowerCase()} ${techNames}`;
};

const matchesCategory = (project, categoryId) => {
  if (categoryId === "ALL") return true;
  const cat = FILTER_CATEGORIES.find((c) => c.id === categoryId);
  if (!cat || !cat.keywords) return true;
  const hay = buildHaystack(project);
  return cat.keywords.some((kw) => hay.includes(kw.toLowerCase()));
};

const matchesSearch = (project, query) => {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return buildHaystack(project).includes(q);
};

const FIGURE_RE = /([~<>≈]?\$?\d[\d,.]*\s?(?:%|\+|x|k|K|M)?\+?)/;

// A figure sitting right after one of these belongs to the sentence — lifting
// it out strands the preposition ("…from 4+ hours to…" -> "…from hours to…").
const BOUND_PREPOSITIONS = /\b(from|to|by|under|over|within|than|of|for|in|at|up)\s*$/i;

// Pull a headline number out of an impact sentence, but only when the
// remainder still reads as a sentence:
// "95% retrieval precision with citation enforcement" -> { value: "95%", label: "retrieval precision…" }
// "Reduced dev time by ~80%" -> null (the figure stays inline instead)
const parseMetric = (sentence) => {
  if (!sentence) return null;
  const m = sentence.match(FIGURE_RE);
  if (!m) return null;
  if (BOUND_PREPOSITIONS.test(sentence.slice(0, m.index))) return null;
  let label = sentence.replace(m[1], "").replace(/\s+/g, " ").trim();
  label = label.replace(/^[-–—:,.\s]+|[-–—:,.\s]+$/g, "");
  if (!label) return null;
  if (label.length > 64) label = label.slice(0, 61) + "…";
  return { value: m[1].trim(), label };
};

// Split a sentence around its first figure so the number can be emphasised
// in place — used for rows where the figure can't be lifted out cleanly.
const splitOnFigure = (sentence) => {
  const m = (sentence || "").match(FIGURE_RE);
  if (!m) return null;
  return {
    before: sentence.slice(0, m.index),
    figure: m[1],
    after: sentence.slice(m.index + m[1].length),
  };
};

// Every impact sentence becomes a row, whether or not it carries a number.
// Numbered ones lead with the figure; the rest read as a plain statement, so
// all three case-study cards share one rhythm instead of the numeric cards
// getting tiles and the others a bulleted fallback.
const buildImpactRows = (impacts, limit = 4) =>
  (impacts || []).slice(0, limit).map((sentence) => {
    const metric = parseMetric(sentence);
    if (metric) return { value: metric.value, label: metric.label };
    // No liftable figure — keep the sentence whole, but light up any number
    // inside it so the row still carries weight.
    return { value: null, label: sentence, inline: splitOnFigure(sentence) };
  });

// Emoji in the source names (🔍, 📄) sit at the wrong weight next to the
// display type — the archive cards keep them, the rail titles don't.
const stripEmoji = (s) =>
  (s || "")
    .replace(
      /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu,
      ""
    )
    .replace(/\s+/g, " ")
    .trim();

// Split "CAMS Lens 🔍 — SEBI-Grounded Compliance Intelligence Platform"
// into a short title and a tagline
const splitName = (name) => {
  if (!name) return { title: "", tagline: "" };
  const parts = name.split(/\s+—\s+|\s+-\s+/);
  if (parts.length >= 2) {
    return {
      title: parts[0].trim(),
      tagline: parts.slice(1).join(" — ").trim(),
    };
  }
  return { title: name.trim(), tagline: "" };
};

const easeInOutCubic = (t) =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

// Chrome routes scrollIntoView() and `scroll-behavior: smooth` through its
// smooth-scroll path, and the sitewide `overflow-x: clip` ancestors kill that
// path stone dead — the hero's scroll cue has never moved the page. Instant
// scrolls still land, so drive the easing a frame at a time ourselves.
const SCROLL_OFFSET = 92; // clears the fixed 74px navbar plus breathing room

const scrollToY = (targetY, duration = 700) => {
  const startY = window.scrollY;
  const delta = targetY - startY;
  if (Math.abs(delta) < 2) return;
  // Nothing to ease for a reader who asked for less motion — or for a tab
  // nobody is looking at, where Chrome suspends rAF and the animation would
  // simply never run.
  if (prefersReducedMotion() || document.visibilityState === "hidden") {
    window.scrollTo({ top: targetY, behavior: "instant" });
    return;
  }
  const startedAt = performance.now();
  const step = (now) => {
    const t = Math.min((now - startedAt) / duration, 1);
    window.scrollTo({
      top: startY + delta * easeInOutCubic(t),
      behavior: "instant",
    });
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
};

const scrollToId = (id) => {
  const el = document.getElementById(id);
  if (!el) return;
  scrollToY(el.getBoundingClientRect().top + window.scrollY - SCROLL_OFFSET);
};

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// Words the hero title cycles through — first one is the widest and
// doubles as the ghost that reserves layout width
const ROTATE_WORDS = ["production.", "products.", "reality.", "impact."];

// ============================================
// Count-up number — animates when scrolled into view
// ============================================
function CountUp({ value, suffix = "" }) {
  const ref = useRef(null);
  const [display, setDisplay] = useState(prefersReducedMotion() ? value : 0);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setDisplay(value);
      return;
    }
    const el = ref.current;
    if (!el) return;
    let raf = null;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        io.disconnect();
        const start = performance.now();
        const dur = 1100;
        const tick = (now) => {
          const t = Math.min((now - start) / dur, 1);
          const eased = 1 - Math.pow(1 - t, 3);
          setDisplay(Math.max(0, Math.min(value, Math.round(eased * value))));
          if (t < 1) raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    return () => {
      io.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [value]);

  return (
    <span ref={ref}>
      {display}
      {suffix}
    </span>
  );
}

// ============================================
// Featured rail — scroll-driven horizontal cinema
// The section pins for N viewport-heights; vertical scroll glides the
// panels sideways with parallax + focus scaling on the active one.
// ============================================
const DECK_HUES = [
  { a: "#ff7847", b: "#ff4d8d" }, // coral → pink
  { a: "#7c5cff", b: "#38bdf8" }, // violet → sky
  { a: "#10b981", b: "#a3e635" }, // emerald → lime
];

// Fraction of each segment a card holds dead centre before gliding on.
// A straight `p * (n - 1)` map centres a card at exactly one scroll offset
// and leaves it drifting off-screen everywhere else — this gives every card
// a dwell band so the resting state is always composed.
const RAIL_HOLD = 0.26;

// Depth of the 3D deck. Off-centre cards swing away on Y, sink back on Z and
// dim toward the page colour, so the rail reads as a stack you're flying
// through rather than a strip sliding past.
const RAIL_ROTATE = 17; // deg at one full panel off centre
const RAIL_DEPTH = 260; // px pushed back
const RAIL_DRIFT = 54; // px of counter-parallax against the track

// Scroll progress (0..1) -> panel position (0..n-1), snapping at each card
const railPosition = (p, n) => {
  if (n < 2) return 0;
  const seg = Math.min(p * (n - 1), n - 1 - 1e-6);
  const i = Math.floor(seg);
  const f = seg - i;
  if (f <= RAIL_HOLD) return i;
  if (f >= 1 - RAIL_HOLD) return i + 1;
  return i + easeInOutCubic((f - RAIL_HOLD) / (1 - 2 * RAIL_HOLD));
};

function FeaturedRail({ items, theme, onExplore }) {
  const sectionRef = useRef(null);
  const viewportRef = useRef(null);
  const trackRef = useRef(null);
  const fillRef = useRef(null);
  const [active, setActive] = useState(0);
  const activeIdxRef = useRef(0);

  useEffect(() => {
    if (prefersReducedMotion()) return;
    const section = sectionRef.current;
    const viewport = viewportRef.current;
    const track = trackRef.current;
    if (!section || !viewport || !track) return;
    const panels = Array.from(track.children);
    const n = panels.length;
    if (n === 0) return;
    let raf = null;

    const update = () => {
      raf = null;
      // Below 900px the CSS falls back to a vertical list — clear inline styles
      if (window.innerWidth <= 900) {
        track.style.transform = "";
        panels.forEach((panel) => {
          const card = panel.firstElementChild;
          if (card) {
            card.style.transform = "";
            card.style.opacity = "";
            card.style.removeProperty("--rail-d");
            card.style.removeProperty("--rail-dist");
          }
        });
        return;
      }
      const rect = section.getBoundingClientRect();
      const vh = window.innerHeight;
      const total = rect.height - vh || 1;
      const p = Math.min(Math.max(-rect.top / total, 0), 1);
      // Measure the panel rather than trusting viewport.clientWidth — the
      // rounded integer drifts against the fractional flex width and the
      // error compounds one panel at a time.
      const step =
        panels[0].getBoundingClientRect().width || viewport.clientWidth;
      const pos = railPosition(p, n);
      // Panels are narrower than the viewport, so the track has to be nudged
      // right to keep the active one centred — the slack either side is what
      // lets the neighbouring cards peek in at the edges.
      const gutter = (viewport.clientWidth - step) / 2;

      track.style.transform = `translate3d(${gutter - pos * step}px, 0, 0)`;

      panels.forEach((panel, i) => {
        const card = panel.firstElementChild;
        if (!card) return;
        const delta = pos - i;
        const dist = Math.min(Math.abs(delta), 1);
        card.style.transform =
          `translateX(${delta * -RAIL_DRIFT}px) ` +
          `translateZ(${-dist * RAIL_DEPTH}px) ` +
          `rotateY(${delta * -RAIL_ROTATE}deg) ` +
          `scale(${1 - dist * 0.04})`;
        card.style.opacity = `${1 - dist * 0.35}`;
        // Consumed by CSS for the scrim and the in-card column parallax
        card.style.setProperty("--rail-d", delta.toFixed(3));
        card.style.setProperty("--rail-dist", dist.toFixed(3));
      });

      // Track the card, not raw scroll, so the bar rests when the card does
      if (fillRef.current) {
        fillRef.current.style.transform = `scaleX(${
          n > 1 ? pos / (n - 1) : 1
        })`;
      }
      const idx = Math.min(Math.round(pos), n - 1);
      if (idx !== activeIdxRef.current) {
        activeIdxRef.current = idx;
        setActive(idx);
      }
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    update();
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [items.length]);

  // Jump to panel i by scrolling the window to the matching rail offset
  const jumpTo = useCallback(
    (i) => {
      const section = sectionRef.current;
      if (!section) return;
      const n = items.length;
      const vh = window.innerHeight;
      const top = section.getBoundingClientRect().top + window.scrollY;
      const total = section.offsetHeight - vh;
      const y = n > 1 ? top + (i / (n - 1)) * total : top;
      // Same dead smooth-scroll path as the hero cue used to take, so the
      // progress dots have never actually jumped either.
      scrollToY(y);
    },
    [items.length]
  );

  return (
    <div
      className="frail"
      ref={sectionRef}
      style={{ "--frail-n": items.length }}
    >
      <div className="frail-viewport" ref={viewportRef}>
        <div className="frail-track" ref={trackRef}>
          {items.map((repo, i) => {
            const { title, tagline } = splitName(repo.name);
            const hue = DECK_HUES[i % DECK_HUES.length];
            const impactRows = buildImpactRows(repo?.details?.impact);
            // Proof the card can carry without a second click: who wrote about
            // it, and — where the real thing can't be shown — what can.
            const newsLinks = repo?.details?.newsLinks || [];
            const liveDemo = repo?.details?.liveDemo;
            const isOngoing = /present/i.test(repo?.details?.timeline || "");
            const year = extractYear(repo?.details?.timeline);
            const isGitHub = repo.url?.includes("github.com");

            return (
              <div className="frail-panel" key={`rail-${i}`}>
                <article
                  className="fdeck-card frail-card"
                  style={{
                    "--hue-a": hue.a,
                    "--hue-b": hue.b,
                  }}
                >
                  <div className="fdeck-glow" aria-hidden="true" />
                  <div className="fdeck-art" aria-hidden="true">
                    <span className="fdeck-art-grid" />
                    <span className="fdeck-orbit fdeck-orbit-1" />
                    <span className="fdeck-orbit fdeck-orbit-2" />
                    <span className="fdeck-comet" />
                  </div>
                  <span className="fdeck-index" aria-hidden="true">
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  {/* Sinks the card toward the page colour as it leaves centre */}
                  <div className="fdeck-scrim" aria-hidden="true" />

                  <div className="fdeck-body">
                    <div className="fdeck-info">
                      <div className="fdeck-meta">
                        <span className="fdeck-chip fdeck-chip-accent">
                          Case study {String(i + 1).padStart(2, "0")}
                        </span>
                        {year && (
                          <span className="fdeck-chip">
                            {isOngoing && (
                              <span
                                className="fdeck-live-dot"
                                aria-hidden="true"
                              />
                            )}
                            {isOngoing ? `${year} — In production` : year}
                          </span>
                        )}
                      </div>

                      <h3 className="fdeck-title">{stripEmoji(title)}</h3>
                      {tagline && <p className="fdeck-tagline">{tagline}</p>}
                      <p className="fdeck-desc">{repo.description}</p>

                      <div className="fdeck-tech">
                        {(repo.languages || []).slice(0, 6).map((l) => (
                          <span className="fdeck-tech-chip" key={l.name}>
                            {l.name}
                          </span>
                        ))}
                      </div>

                      <div className="fdeck-actions">
                        {/* A real href so crawlers reach the prerendered
                            case study; the click is handled in-app. */}
                        <a
                          className="fdeck-btn fdeck-btn-primary"
                          href={`/projects/${projectSlug(repo)}`}
                          onClick={(e) => {
                            e.preventDefault();
                            onExplore(repo);
                          }}
                        >
                          Read case study
                        </a>
                        <a
                          className="fdeck-btn fdeck-btn-ghost"
                          href={repo.url}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          {isGitHub ? (
                            <>
                              <FaGithub aria-hidden="true" /> GitHub
                            </>
                          ) : (
                            <>
                              <FaExternalLinkAlt aria-hidden="true" /> Visit
                              live
                            </>
                          )}
                        </a>
                      </div>

                      {/* A runnable counterpart to a project that can't be
                          shown. Plain anchor rather than <Link> — Jarvis is a
                          heavy interactive page, better off with a fresh
                          mount. Deliberately not a third pill: it is an
                          invitation, and a third pill would wrap the row. */}
                      {liveDemo?.href && (
                        <a
                          className="fdeck-live-link"
                          href={liveDemo.href}
                          title={liveDemo.title}
                        >
                          <span className="fdeck-live-dot" aria-hidden="true" />
                          {liveDemo.label || "Try the live demo"}
                          <span className="fdeck-live-arrow" aria-hidden="true">
                            &rarr;
                          </span>
                        </a>
                      )}
                    </div>

                    {(impactRows.length > 0 || newsLinks.length > 0) && (
                      <div className="fdeck-impact">
                        {impactRows.length > 0 && (
                          <h4 className="fdeck-impact-head">Impact</h4>
                        )}
                        <ul className="fdeck-impact-rows">
                          {impactRows.map((row, ri) => (
                            <li
                              className={`fdeck-impact-row${
                                row.value ? " has-value" : ""
                              }`}
                              key={ri}
                            >
                              {row.value && (
                                <span className="fdeck-impact-value">
                                  {row.value}
                                </span>
                              )}
                              <span className="fdeck-impact-label">
                                {row.inline ? (
                                  <>
                                    {row.inline.before}
                                    <em className="fdeck-impact-figure">
                                      {row.inline.figure}
                                    </em>
                                    {row.inline.after}
                                  </>
                                ) : (
                                  row.label
                                )}
                              </span>
                            </li>
                          ))}
                        </ul>

                        {/* The impact column is the evidence column, so the
                            people who wrote about it belong at the foot of it
                            rather than competing with the CTAs. */}
                        {newsLinks.length > 0 && (
                          <p className="fdeck-press">
                            <span className="fdeck-press-label">
                              <FaNewspaper aria-hidden="true" /> In the press
                            </span>
                            {newsLinks.slice(0, 2).map((link, li) => (
                              <a
                                className="fdeck-press-link"
                                key={li}
                                href={link.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                title={link.title}
                              >
                                {link.source}
                              </a>
                            ))}
                          </p>
                        )}
                      </div>
                    )}
                  </div>
                </article>
              </div>
            );
          })}
        </div>

        {/* Progress rail: 01 ——— 03 with clickable dots */}
        <div className="frail-progress">
          <span className="frail-num">
            {String(active + 1).padStart(2, "0")}
          </span>
          <span className="frail-bar" aria-hidden="true">
            <span className="frail-bar-fill" ref={fillRef} />
          </span>
          <span className="frail-num frail-num-total">
            {String(items.length).padStart(2, "0")}
          </span>
          <span className="frail-dots">
            {items.map((repo, i) => (
              <button
                key={`dot-${i}`}
                type="button"
                className={`frail-dot ${i === active ? "active" : ""}`}
                onClick={() => jumpTo(i)}
                aria-label={`Go to case study ${i + 1}`}
              />
            ))}
          </span>
        </div>
      </div>
    </div>
  );
}

// ============================================
// Page
// ============================================
function Projects(props) {
  const theme = props.theme;
  const history = useHistory();
  const location = useLocation();
  const searchInputRef = useRef(null);
  // The URL is the source of truth for which case study is open:
  // /projects/<slug> opens it, /projects closes it. Back/forward and
  // shared deep links therefore just work.
  const routeSlug = props.match?.params?.slug || null;
  const [selectedProject, setSelectedProject] = useState(() =>
    findProjectBySlug(projects.data, routeSlug)
  );
  const [isModalOpen, setIsModalOpen] = useState(Boolean(selectedProject));
  const [activeCategory, setActiveCategory] = useState(
    () => readFilterUrl(window.location.search).category
  );
  const [searchQuery, setSearchQuery] = useState(
    () => readFilterUrl(window.location.search).query
  );
  const [wordIndex, setWordIndex] = useState(0);
  const agentsKind = useMemo(agentsVariant, []);

  const heroRef = useRef(null);
  const heroSpotRef = useRef(null);
  const heroInnerRef = useRef(null);
  const progressRef = useRef(null);
  const rootRef = useRef(null);

  // Featured = first 3 projects in data (CAMS Lens, CAMSCode, IDP)
  const featuredProjects = useMemo(() => (projects.data || []).slice(0, 3), []);
  const restProjects = useMemo(() => (projects.data || []).slice(3), []);

  // Aggregate metrics for the hero stats
  const stats = useMemo(() => {
    const all = projects.data || [];
    const ai = all.filter((p) => matchesCategory(p, "AI")).length;
    const covered = all.filter(
      (p) => Array.isArray(p?.details?.newsLinks) && p.details.newsLinks.length
    ).length;
    return {
      total: all.length,
      ai,
      production: 4,
      covered: covered || 1,
    };
  }, []);

  // Unique tech names for the marquee strip
  const marqueeTech = useMemo(() => {
    const seen = new Set();
    (projects.data || []).forEach((p) =>
      (p.languages || []).forEach((l) => l.name && seen.add(l.name))
    );
    return Array.from(seen);
  }, []);

  // Filter logic — applied to non-featured cards
  const filteredProjects = useMemo(() => {
    return restProjects.filter(
      (p) => matchesCategory(p, activeCategory) && matchesSearch(p, searchQuery)
    );
  }, [restProjects, activeCategory, searchQuery]);

  // Cycle the hero's rotating word
  useEffect(() => {
    if (prefersReducedMotion()) return;
    const id = setInterval(
      () => setWordIndex((i) => (i + 1) % ROTATE_WORDS.length),
      2600
    );
    return () => clearInterval(id);
  }, []);

  // Cursor-following spotlight behind the hero title (desktop pointers only)
  useEffect(() => {
    if (prefersReducedMotion()) return;
    if (window.matchMedia && !window.matchMedia("(pointer: fine)").matches)
      return;
    const hero = heroRef.current;
    const spot = heroSpotRef.current;
    if (!hero || !spot) return;
    let raf = null;
    let x = 0;
    let y = 0;
    const onMove = (e) => {
      const rect = hero.getBoundingClientRect();
      x = e.clientX - rect.left;
      y = e.clientY - rect.top;
      if (!raf) {
        raf = requestAnimationFrame(() => {
          raf = null;
          spot.style.transform = `translate(${x}px, ${y}px) translate(-50%, -50%)`;
          spot.style.opacity = "1";
        });
      }
    };
    const onLeave = () => {
      spot.style.opacity = "0";
    };
    hero.addEventListener("mousemove", onMove);
    hero.addEventListener("mouseleave", onLeave);
    return () => {
      hero.removeEventListener("mousemove", onMove);
      hero.removeEventListener("mouseleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // Scroll progress bar + hero parallax — single rAF-throttled listener
  useEffect(() => {
    if (prefersReducedMotion()) return;
    let raf = null;
    const update = () => {
      raf = null;
      const y = window.scrollY;
      const doc = document.documentElement;
      const max = doc.scrollHeight - window.innerHeight || 1;
      if (progressRef.current) {
        progressRef.current.style.transform = `scaleX(${Math.min(y / max, 1)})`;
      }
      if (heroInnerRef.current) {
        const fade = Math.min(y / 520, 1);
        heroInnerRef.current.style.transform = `translateY(${y * 0.22}px)`;
        heroInnerRef.current.style.opacity = `${1 - fade * 0.85}`;
      }
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    update();
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // Generic reveal-on-scroll for [data-reveal] elements
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const els = Array.from(root.querySelectorAll("[data-reveal]"));
    if (prefersReducedMotion()) {
      els.forEach((el) => el.classList.add("revealed"));
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("revealed");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, [filteredProjects.length]);

  // State -> URL. replace(), never push(): the back button should leave the
  // page, not walk back through every keystroke. The pathname is carried
  // through untouched so this also runs harmlessly on a /projects/<slug> URL.
  useEffect(() => {
    const next = buildFilterUrl(activeCategory, searchQuery);
    if (next === location.search) return;
    history.replace({ pathname: location.pathname, search: next });
  }, [activeCategory, searchQuery, location.pathname, location.search, history]);

  // URL -> state, but only for real back/forward. Syncing on every location
  // change would fight the user mid-keystroke, since the URL holds a trimmed
  // copy of what they are still typing.
  useEffect(() => {
    if (history.action !== "POP") return;
    const { category, query } = readFilterUrl(location.search);
    setActiveCategory(category);
    setSearchQuery(query);
  }, [location.search, history]);

  // "/" focuses search from anywhere on the page, Escape clears and releases
  // it. The input lives in a toolbar far down the page, so bring it into view
  // rather than letting the browser jump there on focus.
  useEffect(() => {
    const onKeyDown = (e) => {
      const el = document.activeElement;
      const isTyping =
        el &&
        (el.tagName === "INPUT" ||
          el.tagName === "TEXTAREA" ||
          el.isContentEditable);

      if (e.key === "/" && !isTyping && !e.metaKey && !e.ctrlKey && !e.altKey) {
        const input = searchInputRef.current;
        if (!input) return;
        e.preventDefault();
        const rect = input.getBoundingClientRect();
        const offscreen = rect.top < 90 || rect.bottom > window.innerHeight;
        input.focus({ preventScroll: true });
        if (offscreen) scrollToId("project-archive");
        return;
      }

      if (e.key === "Escape" && el === searchInputRef.current) {
        setSearchQuery("");
        el.blur();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  // Opening/closing a case study only navigates. The effect below reacts to
  // the resulting URL and drives the modal, so there is one direction of flow
  // and browser back/forward stays in sync.
  const handleExplore = useCallback(
    (project) =>
      history.push({
        pathname: `/projects/${projectSlug(project)}`,
        search: location.search,
      }),
    [history, location.search]
  );

  // Closing returns you to the archive you were filtering, not a reset one.
  const closeModal = useCallback(
    () => history.push({ pathname: "/projects", search: location.search }),
    [history, location.search]
  );

  useEffect(() => {
    const fromUrl = findProjectBySlug(projects.data, routeSlug);
    if (fromUrl) {
      setSelectedProject(fromUrl);
      setIsModalOpen(true);
      return;
    }
    // An unknown slug is a dead URL — send it back to the index rather than
    // leaving it in the address bar.
    if (routeSlug)
      history.replace({
        pathname: "/projects",
        search: window.location.search,
      });
    // Close, keeping the project mounted long enough for the exit animation.
    setIsModalOpen(false);
    const t = setTimeout(() => setSelectedProject(null), 300);
    return () => clearTimeout(t);
  }, [routeSlug, history]);

  const scrollToArchive = useCallback(() => scrollToId("project-archive"), []);
  const scrollToFeatured = useCallback(
    () => scrollToId("featured-case-studies"),
    []
  );

  // The four hero numbers are the page's real hook, so each one is a way in
  // rather than a decoration: the two countable ones drop you into the archive
  // already filtered, and the two qualitative ones into the case studies that
  // earn them.
  const jumpToArchive = useCallback(
    (category) => {
      setActiveCategory(category);
      setSearchQuery("");
      scrollToId("project-archive");
    },
    []
  );

  return (
    <div
      className="projects-main projects-v2"
      data-theme={theme?.name}
      ref={rootRef}
      style={{
        "--pj-accent": theme.accentColor,
        "--pj-accent-bright": theme.accentBright,
        "--pj-text": theme.text,
        "--pj-sub": theme.secondaryText,
        "--pj-body": theme.body,
        "--pj-card": theme.projectCard,
      }}
    >
      {/* Scroll progress bar */}
      <div className="pj-progress" aria-hidden="true">
        <div className="pj-progress-fill" ref={progressRef} />
      </div>

      <Header theme={theme} setTheme={props.setTheme} />

      {/* ============= HERO ============= */}
      <section className="pj-hero" ref={heroRef}>
        <div className="pj-hero-bg" aria-hidden="true">
          <div className="pj-orb pj-orb-1" />
          <div className="pj-orb pj-orb-2" />
          <div className="pj-orb pj-orb-3" />
          <div className="pj-hero-grid" />
          <div className="pj-hero-spot" ref={heroSpotRef} />
        </div>

        <div className="pj-hero-inner" ref={heroInnerRef}>
          <p className="pj-eyebrow">
            <span className="pj-eyebrow-line" aria-hidden="true" />
            Portfolio — Selected works
          </p>
          <h1 className="pj-hero-title">
            <span className="pj-hero-line">
              {"Ideas, engineered".split(" ").map((word, wi) => (
                <span
                  className="pj-title-word"
                  style={{ animationDelay: `${0.08 + wi * 0.12}s` }}
                  key={wi}
                >
                  {word}&nbsp;
                </span>
              ))}
            </span>
            <span className="pj-hero-line pj-hero-line-accent">
              into{" "}
              <span className="pj-word-rotator">
                {/* Ghost reserves the width of the longest word */}
                <span className="pj-word-ghost" aria-hidden="true">
                  {ROTATE_WORDS[0]}
                </span>
                <span className="pj-word" key={wordIndex}>
                  {ROTATE_WORDS[wordIndex]}
                </span>
              </span>
            </span>
          </h1>
          <p className="pj-hero-sub">{projectsHeader["description"]}</p>

          {/* The only CTA used to be the scroll cue at the very bottom of the
              hero, which sits below the fold on a laptop — and did nothing.
              Both actions live up here now, where they can be seen. */}
          <div className="pj-hero-actions">
            <button
              type="button"
              className="pj-hero-btn is-primary"
              onClick={scrollToFeatured}
            >
              <span>See the case studies</span>
              <span className="pj-hero-btn-arrow" aria-hidden="true">
                &darr;
              </span>
            </button>

            {/* Same direct-download URL as the closing CTA band: it answers
                with Content-Disposition: attachment, so nothing navigates. */}
            <a
              className="pj-hero-btn is-ghost"
              href={resumeDownloadUrl()}
              download={RESUME_FILENAME}
              rel="noopener"
            >
              <FaFileDownload aria-hidden="true" />
              <span>Download r&eacute;sum&eacute;</span>
            </a>
          </div>

          {/* Lil agents strolling on top of the stat tiles. WebGL build by
              default; ?agents=css is the original CSS/SVG pair and
              ?agents=flat the flat-vector experiment. */}
          {agentsKind === "css" && <LilAgents />}
          {agentsKind === "3d" && (
            <React.Suspense fallback={<div style={{ height: 200 }} />}>
              <LilAgents3D />
            </React.Suspense>
          )}
          {agentsKind === "flat" && (
            <React.Suspense fallback={<div style={{ height: 150 }} />}>
              <LilAgentsFlat />
            </React.Suspense>
          )}
          {agentsKind === "lottie" && (
            <React.Suspense fallback={<div style={{ height: 170 }} />}>
              <LilAgentsLottie />
            </React.Suspense>
          )}

          <div className="pj-hero-stats">
            <button
              type="button"
              className="pj-stat"
              onClick={() => jumpToArchive("ALL")}
              aria-label={`Browse all ${stats.total} projects in the archive`}
            >
              <span className="pj-stat-num">
                <CountUp value={stats.total} suffix="+" />
              </span>
              <span className="pj-stat-label">Projects shipped</span>
            </button>
            <button
              type="button"
              className="pj-stat"
              onClick={() => jumpToArchive("AI")}
              aria-label={`Browse the ${stats.ai} AI and agentic systems`}
            >
              <span className="pj-stat-num">
                <CountUp value={stats.ai} suffix="+" />
              </span>
              <span className="pj-stat-label">AI / agentic systems</span>
            </button>
            {/* Neither of these is a filter — the systems that are actually
                running, and the one the press picked up, are the case
                studies. Send the reader there instead. */}
            <button
              type="button"
              className="pj-stat"
              onClick={scrollToFeatured}
              aria-label="See the systems running in production"
            >
              <span className="pj-stat-num">
                <CountUp value={stats.production} />
              </span>
              <span className="pj-stat-label">Running in production</span>
            </button>
            <button
              type="button"
              className="pj-stat"
              onClick={scrollToFeatured}
              aria-label="See the work covered in the press"
            >
              <span className="pj-stat-num">
                <CountUp value={stats.covered} />
              </span>
              <span className="pj-stat-label">Covered in the press</span>
            </button>
          </div>

          <button
            type="button"
            className="pj-scroll-cue"
            onClick={scrollToArchive}
            aria-label="Scroll to projects"
          >
            <span>Scroll to explore</span>
            <span className="pj-scroll-cue-track" aria-hidden="true">
              <span className="pj-scroll-cue-dot" />
            </span>
          </button>
        </div>
      </section>

      {/* ============= FEATURED — STICKY CASE-STUDY DECK ============= */}
      {featuredProjects.length > 0 && (
        <section className="pj-featured" id="featured-case-studies">
          <div className="pj-section-head" data-reveal>
            <span className="pj-section-kicker">01 — Featured</span>
            <h2 className="pj-section-title">Case studies</h2>
            <p className="pj-section-sub">
              Production-grade systems I designed, built, and shipped. Keep
              scrolling — the gallery glides sideways.
            </p>
          </div>
          <FeaturedRail
            items={featuredProjects}
            theme={theme}
            onExplore={handleExplore}
          />
        </section>
      )}

      {/* ============= TECH MARQUEE ============= */}
      <div className="pj-marquee" aria-hidden="true">
        <div className="pj-marquee-track">
          {[0, 1].map((copy) => (
            <div className="pj-marquee-group" key={copy}>
              {marqueeTech.map((t) => (
                <span className="pj-marquee-item" key={`${copy}-${t}`}>
                  {t}
                  <span className="pj-marquee-dot">◆</span>
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* ============= ARCHIVE ============= */}
      <section className="pj-archive" id="project-archive">
        <div className="pj-section-head" data-reveal>
          <span className="pj-section-kicker">02 — The archive</span>
          <h2 className="pj-section-title">Everything else</h2>
          <p className="pj-section-sub">
            {restProjects.length} more experiments, tools, and systems — filter
            by discipline or search the stack.
          </p>
        </div>

        {/* Sticky glass toolbar */}
        <div className="pj-toolbar">
          <div
            className="pj-filter-pills"
            role="tablist"
            aria-label="Filter projects"
          >
            {FILTER_CATEGORIES.map((cat) => {
              const count =
                cat.id === "ALL"
                  ? restProjects.length
                  : restProjects.filter((p) => matchesCategory(p, cat.id))
                      .length;
              const isActive = activeCategory === cat.id;
              return (
                <button
                  key={cat.id}
                  type="button"
                  role="tab"
                  aria-selected={isActive}
                  className={`pj-pill ${isActive ? "active" : ""}`}
                  onClick={() => setActiveCategory(cat.id)}
                >
                  {cat.label}
                  <span className="pj-pill-count">{count}</span>
                </button>
              );
            })}
          </div>

          <div className="pj-search">
            <FaSearch className="pj-search-icon" aria-hidden="true" />
            <input
              type="search"
              className="pj-search-input"
              placeholder="Search projects, tech, keywords…"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label="Search projects"
              ref={searchInputRef}
            />
            {/* A shortcut nobody can see is a shortcut nobody uses */}
            {!searchQuery && (
              <kbd className="pj-search-kbd" aria-hidden="true">
                /
              </kbd>
            )}
          </div>
        </div>

        {/* Grid */}
        <div className="pj-grid">
          {filteredProjects.length === 0 ? (
            <div className="pj-empty">
              <p>No projects match this filter.</p>
              <button
                type="button"
                className="pj-empty-reset"
                onClick={() => {
                  setActiveCategory("ALL");
                  setSearchQuery("");
                }}
              >
                Reset filters
              </button>
            </div>
          ) : (
            filteredProjects.map((repo, i) => (
              <div
                className="pj-grid-item"
                data-reveal
                style={{ "--reveal-delay": `${(i % 6) * 60}ms` }}
                key={`${repo.id}-${repo.name}`}
              >
                <ProjectCard
                  repo={repo}
                  theme={theme}
                  onExplore={handleExplore}
                />
              </div>
            ))
          )}
        </div>
      </section>

      {/* ============= MODAL ============= */}
      <React.Suspense fallback={null}>
        <ProjectModal
          project={selectedProject}
          theme={theme}
          isOpen={isModalOpen}
          onClose={closeModal}
        />
      </React.Suspense>

      {/* ============= CTA BAND =============
          The last thing a recruiter reads. It used to offer only "Explore
          GitHub", which sends an interested reader away at the exact moment
          they're convinced — so the résumé and a way to make contact come
          first, and GitHub stays as the third option. */}
      <section className="pj-cta" data-reveal>
        <span className="pj-cta-aurora" aria-hidden="true" />

        <p className="pj-cta-kicker">If this is the work you're hiring for</p>
        <h2 className="pj-cta-title">
          Let's talk about what I could build <em>with your team</em>.
        </h2>
        <p className="pj-cta-sub">
          The full résumé, or a short conversation — whichever is quicker for
          you.
        </p>

        <div className="pj-cta-actions">
          {/* A real download, not a Drive preview tab: the direct-download URL
              answers with Content-Disposition: attachment, so the file lands in
              the visitor's Downloads folder and this page stays open. Hence no
              target="_blank" — nothing here navigates away. */}
          <a
            className="pj-cta-btn is-primary"
            href={resumeDownloadUrl()}
            download={RESUME_FILENAME}
            rel="noopener"
          >
            <FaFileDownload aria-hidden="true" />
            <span>Download résumé</span>
          </a>

          <Link className="pj-cta-btn is-secondary" to="/contact">
            <FaPaperPlane aria-hidden="true" />
            <span>Get in touch</span>
          </Link>

          <a
            className="pj-cta-btn is-ghost"
            href={socialMediaLinks.github}
            target="_blank"
            rel="noopener noreferrer"
          >
            <FaGithub aria-hidden="true" />
            <span>Explore GitHub</span>
            <span className="pj-cta-arrow" aria-hidden="true">
              →
            </span>
          </a>
        </div>
      </section>

      <Footer theme={props.theme} onToggle={props.onToggle} />
    </div>
  );
}

export { extractYear };
export default Projects;
